#!/usr/bin/env python3
"""Real Metal: format-specialized and generic BC transcodes must match exactly."""
from pathlib import Path
import tempfile,subprocess
repo=Path(__file__).resolve().parents[3]
s=(repo/'src/Cafe/HW/Latte/Renderer/Metal/MetalBCTranscodeShaderSource.h').read_text()
s=s[s.index('R"(')+3:s.rindex(')"')]
reference=s.replace('constant uint cemuBCFormat [[function_constant(0)]];','').replace('const uint format = is_function_constant_defined(cemuBCFormat) ? cemuBCFormat : params.format;','const uint format = params.format;')
fixture='#import <Metal/Metal.h>\n#import <Foundation/Foundation.h>\n#include <cstdio>\n#include <cstring>\n#include <algorithm>\n#include <vector>\nint main(int argc,char**argv){@autoreleasepool{\n id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*e=nil;\n NSString*a=[NSString stringWithContentsOfFile:@(argv[1]) encoding:NSUTF8StringEncoding error:&e];\n NSString*b=[NSString stringWithContentsOfFile:@(argv[2]) encoding:NSUTF8StringEncoding error:&e];\n id<MTLLibrary>la=[d newLibraryWithSource:a options:nil error:&e],lb=[d newLibraryWithSource:b options:nil error:&e];if(!la||!lb){NSLog(@"%@",e);return 1;}\n auto q=[d newCommandQueue];auto input=[d newBufferWithLength:65536 options:MTLResourceStorageModeShared];uint32_t seed=42;\n for(int i=0;i<65536;i++){seed=1664525*seed+1013904223;((uint8_t*)input.contents)[i]=seed>>24;}\n for(uint32_t f=0;f<7;f++){\n auto fn=[la newFunctionWithName:@"transcodeBCToETC"];auto cv=[MTLFunctionConstantValues new];[cv setConstantValue:&f type:MTLDataTypeUInt atIndex:0];\n auto sf=[lb newFunctionWithName:@"transcodeBCToETC" constantValues:cv error:&e];\n id<MTLComputePipelineState> ps[3]={[d newComputePipelineStateWithFunction:fn error:&e],[d newComputePipelineStateWithFunction:sf error:&e],[d newComputePipelineStateWithFunction:[lb newFunctionWithName:@"transcodeBCToETC" constantValues:[MTLFunctionConstantValues new] error:&e] error:&e]};if(!ps[0]||!ps[1]||!ps[2]){NSLog(@"%@",e);return 2;}\n id<MTLBuffer> out[3]={[d newBufferWithLength:65536 options:MTLResourceStorageModeShared],[d newBufferWithLength:65536 options:MTLResourceStorageModeShared],[d newBufferWithLength:65536 options:MTLResourceStorageModeShared]};\n uint32_t p[8]={64,64,f,253,255,0,0,0};std::vector<double> t[3];\n for(int trial=0;trial<6;trial++)for(int k=0;k<3;k++){\n auto cb=[q commandBuffer];auto enc=[cb computeCommandEncoder];[enc setComputePipelineState:ps[k]];[enc setBuffer:input offset:0 atIndex:0];[enc setBuffer:out[k] offset:0 atIndex:1];[enc setBytes:p length:sizeof(p) atIndex:2];[enc dispatchThreads:MTLSizeMake(64,64,1) threadsPerThreadgroup:MTLSizeMake(8,8,1)];[enc endEncoding];[cb commit];[cb waitUntilCompleted];if(cb.status!=MTLCommandBufferStatusCompleted){NSLog(@"%@",cb.error);return 3;}if(trial)t[k].push_back((cb.GPUEndTime-cb.GPUStartTime)*1000);\n }\n size_t bytes=4096*((f<=2||f>=5)?16:8);if(memcmp(out[0].contents,out[1].contents,bytes)||memcmp(out[0].contents,out[2].contents,bytes)){printf("MISMATCH %u\\n",f);return 4;}\n for(auto&v:t)std::sort(v.begin(),v.end());printf("format%u identical=%zu dynamicMs=%.3f specializedMs=%.3f\\n",f,bytes,t[0][2],t[1][2]);fflush(stdout);\n }\n}}\n'
with tempfile.TemporaryDirectory(prefix='cemu-bc-specialization-') as d:
 d=Path(d);(d/'generic.metal').write_text(reference);(d/'specialized.metal').write_text(s);(d/'test.mm').write_text(fixture)
 subprocess.run(['xcrun','clang++','-std=c++20','-O2','-fobjc-arc',str(d/'test.mm'),'-framework','Metal','-framework','Foundation','-o',str(d/'test')],check=True)
 subprocess.run([str(d/'test'),str(d/'generic.metal'),str(d/'specialized.metal')],check=True)
